create extension if not exists pgcrypto;
create table if not exists public.products(id uuid primary key default gen_random_uuid(),slug text unique not null,name text not null,description text not null default '',price bigint not null check(price>=0),image_url text,category text not null default 'General',stock integer not null default 0 check(stock>=0),is_active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.orders(id uuid primary key default gen_random_uuid(),order_number text unique not null,guest_token_hash text not null,customer_name text not null,email text not null,phone text not null,shipping_address jsonb not null,subtotal bigint not null,shipping_cost bigint not null,total_amount bigint not null,currency text not null default 'IDR' check(currency='IDR'),order_status text not null default 'pending_payment',payment_status text not null default 'creating',stock_restored_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id),product_id uuid references public.products(id),product_name text not null,unit_price bigint not null,quantity int not null check(quantity>0),line_total bigint not null);
create table if not exists public.payments(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id),merchant_order_id text unique not null,duitku_reference text unique,payment_url text,amount bigint not null,status text not null default 'pending',provider_response jsonb,callback_payload jsonb,created_at timestamptz not null default now());
create table if not exists public.checkout_idempotency(id uuid primary key default gen_random_uuid(),key_hash text unique not null,payload_hash text not null,order_id uuid references public.orders(id),created_at timestamptz not null default now());
alter table public.products enable row level security;alter table public.orders enable row level security;alter table public.order_items enable row level security;alter table public.payments enable row level security;alter table public.checkout_idempotency enable row level security;
create policy "Public active catalogue" on public.products for select to anon,authenticated using(is_active);grant select on public.products to anon,authenticated;revoke all on public.orders,public.order_items,public.payments,public.checkout_idempotency from anon,authenticated;
create or replace function public.create_store_order(p_no text,p_token text,p_name text,p_email text,p_phone text,p_address jsonb,p_shipping bigint,p_items jsonb,p_key text,p_hash text) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare old public.checkout_idempotency%rowtype;pr public.products%rowtype;it jsonb;oid uuid;sub bigint:=0;q int;
begin delete from public.checkout_idempotency where created_at<now()-interval '24 hours';select * into old from public.checkout_idempotency where key_hash=p_key for update;if found then if old.payload_hash<>p_hash then raise exception 'IDEMPOTENCY_CONFLICT';end if;if old.order_id is not null then return jsonb_build_object('order_id',old.order_id);end if;else insert into public.checkout_idempotency(key_hash,payload_hash) values(p_key,p_hash);end if;
if jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items)=0 then raise exception 'CART_EMPTY';end if;
for it in select value from jsonb_array_elements(p_items) loop q:=(it->>'quantity')::int;if q<1 or q>50 then raise exception 'INVALID_QUANTITY';end if;select * into pr from public.products where id=(it->>'product_id')::uuid and is_active for update;if not found or pr.stock<q then raise exception 'INSUFFICIENT_STOCK';end if;sub:=sub+pr.price*q;end loop;
insert into public.orders(order_number,guest_token_hash,customer_name,email,phone,shipping_address,subtotal,shipping_cost,total_amount) values(p_no,p_token,p_name,p_email,p_phone,p_address,sub,p_shipping,sub+p_shipping) returning id into oid;
insert into public.payments(order_id,merchant_order_id,amount,status) values(oid,p_no,sub+p_shipping,'creating');
for it in select value from jsonb_array_elements(p_items) loop q:=(it->>'quantity')::int;select * into pr from public.products where id=(it->>'product_id')::uuid for update;update public.products set stock=stock-q where id=pr.id;insert into public.order_items(order_id,product_id,product_name,unit_price,quantity,line_total) values(oid,pr.id,pr.name,pr.price,q,pr.price*q);end loop;update public.checkout_idempotency set order_id=oid where key_hash=p_key;return jsonb_build_object('order_id',oid);end$$;
create or replace function public.apply_duitku_callback(p_order text,p_ref text,p_amount bigint,p_status text,p_payload jsonb) returns text language plpgsql security definer set search_path=public,pg_temp as $$
declare pay public.payments%rowtype;o public.orders%rowtype;
begin select * into pay from public.payments where merchant_order_id=p_order for update;if not found then return 'NOT_FOUND';end if;select * into o from public.orders where id=pay.order_id for update;if pay.amount<>p_amount or o.total_amount<>p_amount or (pay.duitku_reference is not null and pay.duitku_reference<>p_ref) then update public.payments set status='needs_review',callback_payload=p_payload where id=pay.id;update public.orders set payment_status='needs_review',order_status='payment_review' where id=o.id;return 'REVIEW';end if;if pay.status='paid' then return 'ALREADY_PAID';end if;if pay.status in('failed','expired') and p_status='paid' then update public.payments set status='needs_review',callback_payload=p_payload where id=pay.id;update public.orders set payment_status='needs_review',order_status='payment_review' where id=o.id;return 'CONFLICT_REVIEW';end if;
if p_status='paid' then update public.payments set status='paid',callback_payload=p_payload where id=pay.id;update public.orders set payment_status='paid',order_status='processing' where id=o.id;return 'SUCCESS';elsif p_status in('failed','expired') then update public.payments set status=p_status,callback_payload=p_payload where id=pay.id;if o.stock_restored_at is null then update public.products p set stock=p.stock+i.qty from (select product_id,sum(quantity) as qty from public.order_items where order_id=o.id and product_id is not null group by product_id) i where i.product_id=p.id;update public.orders set payment_status=p_status,order_status='cancelled',stock_restored_at=now() where id=o.id;end if;return 'SUCCESS';else update public.payments set status='needs_review',callback_payload=p_payload where id=pay.id;update public.orders set payment_status='needs_review',order_status='payment_review' where id=o.id;return 'REVIEW';end if;end$$;
create or replace function public.get_guest_order(p_no text,p_token text) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare o public.orders%rowtype;begin select * into o from public.orders where order_number=p_no and guest_token_hash=p_token;if not found then raise exception 'ORDER_NOT_FOUND';end if;return jsonb_build_object('order_number',o.order_number,'order_status',o.order_status,'payment_status',o.payment_status,'total_amount',o.total_amount,'currency',o.currency);end$$;
revoke all on function public.create_store_order(text,text,text,text,text,jsonb,bigint,jsonb,text,text),public.apply_duitku_callback(text,text,bigint,text,jsonb),public.get_guest_order(text,text) from public,anon,authenticated;grant execute on function public.create_store_order(text,text,text,text,text,jsonb,bigint,jsonb,text,text),public.apply_duitku_callback(text,text,bigint,text,jsonb),public.get_guest_order(text,text) to service_role;